import subprocess, re
def graph(cwd):
    out = subprocess.run(['go','mod','graph'], cwd=cwd, capture_output=True, text=True).stdout
    mods = {}
    for line in out.splitlines():
        for tok in line.split():
            if '@' in tok:
                name, ver = tok.rsplit('@',1)
                mods.setdefault(name, set()).add(ver)
    return mods
old = graph('/tmp/netcheck')
new = graph('/home/kara/off-by-one')
def major(v):
    v = v.lstrip('v')
    m = re.match(r'(\d+)', v)
    return m.group(1) if m else None
jumps = []
for name in sorted(set(old) & set(new)):
    om = {major(v) for v in old[name]}
    nm = {major(v) for v in new[name]}
    if om != nm:
        jumps.append((name, sorted(old[name]), sorted(new[name])))
print("MAJOR JUMPS:", len(jumps))
for j in jumps: print("  ", j)
print()
print("=== prometheus family before -> after ===")
for name in sorted(n for n in set(old)|set(new) if 'prometheus' in n):
    print(f"  {name}: {sorted(old.get(name,[]))} -> {sorted(new.get(name,[]))}")
print()
print("=== x/net ===")
print("  before:", sorted(old.get('golang.org/x/net',[])))
print("  after :", sorted(new.get('golang.org/x/net',[])))
EOF
